
        const GRAPH_DATA = {"nodes": [{"id": "m1", "next_best": false, "type": "macro", "label": "Khai thác dữ liệu và thông tin", "resources": [], "color": "#00ffcc", "val": 25}, {"id": "m2", "next_best": false, "type": "macro", "label": "Giao tiếp và hợp tác trong môi trường số", "resources": [], "color": "#00ffcc", "val": 25}, {"id": "m3", "next_best": false, "type": "macro", "label": "Sáng tạo nội dung số", "resources": [], "color": "#00ffcc", "val": 25}, {"id": "m4", "next_best": false, "type": "macro", "label": "An toàn thông tin", "resources": [], "color": "#00ffcc", "val": 25}, {"id": "m5", "next_best": false, "type": "macro", "label": "Giải quyết vấn đề", "resources": [], "color": "#00ffcc", "val": 25}, {"id": "m6", "next_best": false, "type": "macro", "label": "Ứng dụng trí tuệ nhân tạo", "resources": [], "color": "#00ffcc", "val": 25}, {"id": "m1_Meso_1", "next_best": true, "type": "meso", "label": "Phần 1", "micro_children": [{"id": "c1.1", "title": "Duyệt, tìm kiếm và lọc dữ liệu, thông tin", "content": "Học phần này trang bị kỹ năng duyệt, tìm kiếm và lọc dữ liệu, thông tin số. Bao gồm việc phân biệt dữ liệu thô, thông tin, tri thức, nhận biết các loại dữ liệu và đặc điểm dữ liệu số. Sinh viên học cách đọc lướt, xác định thông tin cần thiết và xây dựng chiến lược duyệt trang web, tài liệu số hiệu quả. Kỹ thuật tìm kiếm nâng cao trên Google, Bing cùng với việc sử dụng công cụ tìm kiếm học thuật cũng được giới thiệu.", "resources": []}, {"id": "c1.2", "title": "Đánh giá dữ liệu, thông tin và nội dung số", "content": "Mục này tập trung vào việc đánh giá độ tin cậy và chính xác của dữ liệu, thông tin số. Sinh viên được học về các tiêu chí đánh giá như mô hình CRAAP và phương pháp SIFT. Đồng thời, học viên thực hành phân tích, làm sạch dữ liệu, nhận diện thông tin sai lệch và biết cách vận dụng AI để hỗ trợ quá trình kiểm tra độ tin cậy của nội dung số.", "resources": []}, {"id": "c1.3", "title": "Quản lý dữ liệu, thông tin và nội dung số", "content": "Học phần này hướng dẫn sinh viên các kỹ năng quản lý dữ liệu cá nhân và tổ chức, bao gồm lưu trữ và sao lưu dữ liệu một cách an toàn. Bên cạnh đó, sinh viên học cách bảo mật thông tin, quyền riêng tư và thiết lập quyền truy cập, chia sẻ dữ liệu hiệu quả, cũng như quản lý phiên bản khi tổ chức lưu trữ và chia sẻ dữ liệu.", "resources": []}], "resources": [], "val": 15, "prerequisites": []}, {"id": "m2_Meso_1", "next_best": false, "type": "meso", "label": "Phần 1", "micro_children": [{"id": "c2.1", "title": "Tương tác và chia sẻ thông tin qua công nghệ số", "content": "Mô-đun này giúp sinh viên hiểu cách tương tác hiệu quả thông qua công nghệ số bằng việc lựa chọn và sử dụng các công cụ giao tiếp phù hợp như email, chat, video call. Sinh viên cũng học cách chia sẻ thông tin và nội dung qua các nền tảng như Google Drive, OneDrive một cách hiệu quả và an toàn.", "resources": []}, {"id": "c2.2", "title": "Hợp tác và thực hiện trách nhiệm công dân số", "content": "Sinh viên được học cách sử dụng công nghệ số để thực hiện trách nhiệm công dân, như tham gia vào các hoạt động xã hội số. Đồng thời, học viên sẽ rèn luyện kỹ năng hợp tác thông qua các công cụ cộng tác trực tuyến như Google Docs, Trello để làm việc nhóm và xây dựng nội dung chung.", "resources": []}, {"id": "c2.3", "title": "Quy tắc ứng xử và quản lý danh tính số", "content": "Học phần này tập trung vào việc rèn luyện sinh viên giao tiếp văn minh, tôn trọng và phù hợp trong môi trường số. Sinh viên học cách quản lý danh tính số cá nhân trên các nền tảng khác nhau, bảo vệ dữ liệu cá nhân và danh tính số, đồng thời thực hiện quy tắc ứng xử trên mạng.", "resources": []}], "resources": [], "val": 15, "prerequisites": ["m1_Meso_1"]}, {"id": "m3_Meso_1", "next_best": false, "type": "meso", "label": "Phần 1", "micro_children": [{"id": "c3.1", "title": "Phát triển nội dung số", "content": "Mô-đun này trang bị cho sinh viên kỹ năng phát triển nội dung số, bắt đầu từ việc phân tích mục tiêu và đối tượng của nội dung. Sinh viên học cách lập kế hoạch nội dung, xác định loại nội dung phù hợp và hiểu các yêu cầu của từng nền tảng. Khả năng sáng tạo kịch bản, thiết kế hình ảnh và biên tập video cũng được đề cập.", "resources": []}, {"id": "c3.2", "title": "Tích hợp và tạo lập lại nội dung số", "content": "Sinh viên học cách thu thập, phân loại và đánh giá nội dung số hiện có. Dựa trên đó, họ sẽ lập dàn ý hoặc storyboard cho nội dung mới và áp dụng các công cụ biên tập để tạo ra nội dung mới phù hợp về định dạng và mục tiêu, như tạo slide từ bài viết hoặc video từ blog.", "resources": []}, {"id": "c3.3", "title": "Bản quyền và giấy phép nội dung số", "content": "Học phần này giúp sinh viên hiểu về khái niệm bản quyền, nhận diện các yếu tố dễ vi phạm bản quyền trong nội dung số như hình ảnh, nhạc nền, logo. Sinh viên cũng được hướng dẫn cách tra cứu, phân loại các dạng giấy phép phổ biến và sử dụng nội dung đúng theo quy định.", "resources": []}], "resources": [], "val": 15, "prerequisites": ["m1_Meso_1"]}, {"id": "m4_Meso_1", "next_best": false, "type": "meso", "label": "Phần 1", "micro_children": [{"id": "c4.1", "title": "Nhận diện rủi ro an toàn thông tin", "content": "Mô-đun này tập trung vào việc giúp sinh viên nhận diện các mối đe dọa và rủi ro tiềm ẩn trong môi trường số. Bao gồm các loại tấn công mạng phổ biến, các lỗ hổng bảo mật và cách thức mà kẻ xấu có thể lợi dụng để xâm phạm thông tin cá nhân và dữ liệu.", "resources": []}, {"id": "c4.2", "title": "Biện pháp đảm bảo an toàn thông tin cá nhân và dữ liệu", "content": "Sinh viên được trang bị các kiến thức và kỹ năng cần thiết để áp dụng các biện pháp bảo vệ an toàn thông tin cá nhân và dữ liệu. Học phần bao gồm việc thiết lập mật khẩu mạnh, sử dụng xác thực hai yếu tố, nhận biết các email lừa đảo (phishing) và cách phòng tránh.", "resources": []}, {"id": "c4.3", "title": "Bảo mật và quyền riêng tư trên mạng", "content": "Phần này đi sâu vào các khía cạnh bảo mật và quyền riêng tư trên không gian mạng. Sinh viên học cách quản lý cài đặt riêng tư trên mạng xã hội và các ứng dụng, hiểu về mã hóa dữ liệu và các quy định pháp luật liên quan đến bảo vệ dữ liệu cá nhân.", "resources": []}], "resources": [], "val": 15, "prerequisites": ["m1_Meso_1"]}, {"id": "m5_Meso_1", "next_best": false, "type": "meso", "label": "Phần 1", "micro_children": [{"id": "c5.1", "title": "Phân tích vấn đề và tư duy logic", "content": "Mô-đun này phát triển khả năng phân tích vấn đề một cách logic và có hệ thống cho sinh viên. Học viên học cách xác định nguyên nhân gốc rễ của vấn đề, chia nhỏ vấn đề phức tạp thành các phần nhỏ hơn và áp dụng tư duy phản biện để đánh giá các giải pháp tiềm năng.", "resources": []}, {"id": "c5.2", "title": "Sử dụng công cụ số để giải quyết vấn đề", "content": "Sinh viên được hướng dẫn cách tận dụng các công cụ số để hỗ trợ quá trình giải quyết vấn đề. Điều này bao gồm việc sử dụng phần mềm quản lý dự án, công cụ cộng tác, nền tảng phân tích dữ liệu và các ứng dụng khác để tìm ra giải pháp sáng tạo và hiệu quả.", "resources": []}, {"id": "c5.3", "title": "Đánh giá và lựa chọn giải pháp", "content": "Phần này tập trung vào việc phát triển kỹ năng đánh giá các giải pháp đã đề xuất dựa trên các tiêu chí như tính khả thi, hiệu quả, chi phí và rủi ro. Sinh viên học cách đưa ra quyết định dựa trên dữ liệu và lựa chọn giải pháp tối ưu nhất cho vấn đề đặt ra.", "resources": []}], "resources": [], "val": 15, "prerequisites": ["m1_Meso_1"]}, {"id": "m6_Meso_1", "next_best": false, "type": "meso", "label": "Phần 1", "micro_children": [{"id": "c6.1", "title": "Giới thiệu về Trí tuệ nhân tạo (AI)", "content": "Mô-đun này cung cấp kiến thức cơ bản về Trí tuệ nhân tạo (AI), bao gồm lịch sử phát triển, các khái niệm cốt lõi và các loại hình AI phổ biến như học máy, học sâu. Sinh viên hiểu được tiềm năng và tác động của AI trong các lĩnh vực khác nhau của đời sống và công việc.", "resources": []}, {"id": "c6.2", "title": "Ứng dụng AI trong học tập và nghiên cứu", "content": "Sinh viên khám phá cách ứng dụng các công cụ AI để nâng cao hiệu quả học tập và nghiên cứu. Bao gồm việc sử dụng AI để tóm tắt tài liệu, tìm kiếm thông tin, hỗ trợ viết lách, phân tích dữ liệu học tập và cá nhân hóa lộ trình học tập.", "resources": []}, {"id": "c6.3", "title": "Ứng dụng AI trong công việc thực tiễn", "content": "Mô-đun này tập trung vào các ứng dụng thực tế của AI trong môi trường làm việc. Sinh viên tìm hiểu cách AI có thể tự động hóa các tác vụ lặp đi lặp lại, hỗ trợ ra quyết định, phân tích thị trường, dự đoán xu hướng và cải thiện năng suất lao động trong nhiều ngành nghề.", "resources": []}], "resources": [], "val": 15, "prerequisites": ["m1_Meso_1"]}], "links": [{"source": "m1", "target": "m1_Meso_1", "relation": "contains"}, {"source": "m2", "target": "m2_Meso_1", "relation": "contains"}, {"source": "m3", "target": "m3_Meso_1", "relation": "contains"}, {"source": "m4", "target": "m4_Meso_1", "relation": "contains"}, {"source": "m5", "target": "m5_Meso_1", "relation": "contains"}, {"source": "m6", "target": "m6_Meso_1", "relation": "contains"}, {"source": "m1", "target": "m2", "relation": "macro_path"}, {"source": "m2", "target": "m3", "relation": "macro_path"}, {"source": "m3", "target": "m4", "relation": "macro_path"}, {"source": "m4", "target": "m5", "relation": "macro_path"}, {"source": "m5", "target": "m6", "relation": "macro_path"}, {"source": "m1_Meso_1", "target": "m2_Meso_1", "relation": "prerequisite_for"}, {"source": "m1_Meso_1", "target": "m3_Meso_1", "relation": "prerequisite_for"}, {"source": "m1_Meso_1", "target": "m4_Meso_1", "relation": "prerequisite_for"}, {"source": "m1_Meso_1", "target": "m5_Meso_1", "relation": "prerequisite_for"}, {"source": "m1_Meso_1", "target": "m6_Meso_1", "relation": "prerequisite_for"}]};
        const USER_STATE = {
            "mastery": {},
            "inferred_blooms": {}
        };
        const CHAPTER_LIST = [{"id": "m1", "title": "Khai thác dữ liệu và thông tin", "order": 1}, {"id": "m2", "title": "Giao tiếp và hợp tác trong môi trường số", "order": 2}, {"id": "m3", "title": "Sáng tạo nội dung số", "order": 3}, {"id": "m4", "title": "An toàn thông tin", "order": 4}, {"id": "m5", "title": "Giải quyết vấn đề", "order": 5}, {"id": "m6", "title": "Ứng dụng trí tuệ nhân tạo", "order": 6}];
        let Graph = null;

        function togglePanel(id) {
            const el = document.getElementById(id);
            if (el) {
                el.classList.toggle('collapsed');
                const icon = el.querySelector('.toggle-icon');
                if (icon) {
                    icon.innerText = el.classList.contains('collapsed') ? 'expand_more' : 'expand_more';
                    // The icon rotation is handled by CSS, but we could change the icon name if desired.
                    // Using expand_more and rotating it -90deg looks like a chevron pointing right/left.
                }
            }
        }

        function getShortLabel(node) {
            if (node.type === 'macro') {
                const match = node.id.match(/(\d+)/);
                if (match) {
                    const num = match[1];
                    if (num === '999') return '✉ Phụ lục';
                    return 'Ch.' + num + ': ' + (node.label || '').substring(0, 14);
                }
                return (node.label || node.id).substring(0, 16);
            }
            if (node.micro_children && node.micro_children.length > 0) {
                const t = node.micro_children[0].title || node.label || '';
                return t.length > 20 ? t.substring(0, 18) + '…' : t;
            }
            return (node.label || node.id).substring(0, 18);
        }

        function focusChapter(chapterId) {
            const node = GRAPH_DATA.nodes.find(n => n.id === chapterId);
            if (node && Graph) {
                Graph.cameraPosition(
                    { x: node.x * 1.6, y: node.y * 1.6, z: node.z * 1.6 },
                    node, 1500
                );
            }
        }

        function renderProgressBar() {
            const container = document.getElementById('progress-chapters');
            if (!container) return;
            container.innerHTML = '';
            CHAPTER_LIST.forEach((ch, idx) => {
                const mesoNodes = GRAPH_DATA.nodes.filter(n => n.type === 'meso' && n.id.startsWith(ch.id + '_'));
                let totalM = 0, cnt = 0;
                mesoNodes.forEach(mn => { totalM += getMasteryLevel(mn.id); cnt++; });
                const pct = cnt > 0 ? Math.round((totalM / cnt) * 100) : 0;
                const item = document.createElement('div');
                item.className = 'prog-item' + (pct >= 80 ? ' mastered' : '');
                const shortTitle = ch.title.length > 10 ? ch.title.substring(0, 8) + '…' : ch.title;
                item.innerHTML = '<div class="prog-label">' + shortTitle + '</div><div class="prog-bar"><div class="prog-fill" style="width:' + pct + '%"></div></div><div class="prog-pct">' + pct + '%</div>';
                item.onclick = function() { focusChapter(ch.id); };
                container.appendChild(item);
                if (idx < CHAPTER_LIST.length - 1) {
                    const arrow = document.createElement('span');
                    arrow.className = 'prog-arrow';
                    arrow.textContent = '→';
                    container.appendChild(arrow);
                }
            });
        }

        function renderChapterNav() {
            const container = document.getElementById('chapter-list');
            if (!container) return;
            container.innerHTML = '';
            CHAPTER_LIST.forEach(ch => {
                const item = document.createElement('div');
                item.className = 'nav-item';
                item.innerHTML = '<span class="material-icons" style="font-size:14px;color:var(--accent);">folder</span> ' + ch.title;
                item.onclick = function() { focusChapter(ch.id); };
                container.appendChild(item);
            });
        }


        function getMasteryLevel(id) { 
            const node = GRAPH_DATA.nodes.find(n => n.id === id);
            if (node && node.type === 'meso') {
                let total = 0, count = 0;
                (node.micro_children || []).forEach(c => {
                    total += (USER_STATE.mastery[c.id] || 0);
                    count++;
                });
                return count > 0 ? total / count : 0;
            }
            return USER_STATE.mastery[id] || 0; 
        }
        
        function getBloomLevel(id) {
            const node = GRAPH_DATA.nodes.find(n => n.id === id);
            if (node && node.type === 'meso') {
                let total = 0, count = 0;
                (node.micro_children || []).forEach(c => {
                    total += (USER_STATE.inferred_blooms[c.id] || 0);
                    count++;
                });
                return count > 0 ? total / count : 0;
            }
            return USER_STATE.inferred_blooms[id] || 0; 
        }

        function getNodeStatus(n) {
            if (n.type === 'macro') return 'macro';
            const m = getMasteryLevel(n.id);
            if (m >= 0.8) return 'mastered';
            if (m >= 0.4) return 'learning';
            return 'weak';
        }
        
        function getNodeColor(n) {
            if (n.type === 'macro') return 'hsl(210, 80%, 60%)'; // Solid Blue
            
            const bloom = getBloomLevel(n.id);
            if (bloom === 0) return 'hsl(210, 20%, 30%)'; // Uncharted (Gray)
            if (bloom < 1.0) return 'hsl(210, 20%, 40%)'; 
            
            let h = 200, s = 80, l = 50;
            if (bloom < 2.0) { // L1 - Remember
                h = 200; s = 80; l = 50;
            } else if (bloom < 3.0) { // L2 - Understand
                h = 140; s = 70; l = 45;
            } else if (bloom < 4.0) { // L3 - Apply
                h = 45; s = 90; l = 50;
            } else if (bloom < 5.0) { // L4 - Analyze
                h = 20; s = 85; l = 55;
            } else { // L5/L6 - Mastery
                h = 280; s = 80; l = 60;
            }
            return `hsl(${h}, ${s}%, ${l}%)`;
        }
        
        function isLocked(n) {
            if (n.type === 'macro') return false;
            return (n.prerequisites || []).some(p => getMasteryLevel(p) < 0.6);
        }
        function updateStats() {
            let m=0, l=0, w=0;
            GRAPH_DATA.nodes.forEach(n => {
                if (n.type !== 'macro') {
                    const s = getNodeStatus(n);
                    if (s === 'mastered') m++; else if (s === 'learning') l++; else w++;
                }
            });
            document.getElementById('stat-mastered').innerText = m;
            document.getElementById('stat-learning').innerText = l;
            document.getElementById('stat-weak').innerText = w;
        }
        function closePanel() {
            document.getElementById('info-panel').classList.remove('visible');
            window.currentNodeId = null;
        }
        function startAction(type) {
            if (!window.currentNodeId) return;
            const node = GRAPH_DATA.nodes.find(n => n.id === window.currentNodeId);
            const payload = { 
                id: window.currentNodeId, 
                action: type,
                label: document.getElementById('info-title').innerText,
                children: node && node.micro_children ? node.micro_children : []
            };
            if (window.parent) window.parent.postMessage({ type: 'graph3d_action', payload }, '*');
            const t = document.createElement('div'); t.className='toast'; t.innerText='🚀 Đang mở '+( type==='video'?'Bài giảng':'Bloom Hub');
            document.getElementById('toast-container').appendChild(t);
            setTimeout(() => t.remove(), 2500);
        }

        function startActionForResource(childId, type, url) {
            if (!window.currentNodeId) return;
            const node = GRAPH_DATA.nodes.find(n => n.id === window.currentNodeId);
            const payload = { 
                id: window.currentNodeId, 
                action: type,
                label: document.getElementById('info-title').innerText,
                children: node && node.micro_children ? node.micro_children : [],
                selected_child: childId,
                target_url: url
            };
            if (window.parent) window.parent.postMessage({ type: 'graph3d_action', payload }, '*');
            const t = document.createElement('div'); t.className='toast'; t.innerText='🚀 Đang mở Tài liệu/Bài giảng';
            document.getElementById('toast-container').appendChild(t);
            setTimeout(() => t.remove(), 2500);
        }
        
        const BLOOM_LABELS = {1:'Ghi nhớ',2:'Hiểu',3:'Áp dụng',4:'Phân tích',5:'Đánh giá',6:'Sáng tạo'};
        const BLOOM_COLORS = {1:'#60a5fa',2:'#4ade80',3:'#fbbf24',4:'#fb923c',5:'#f87171',6:'#c084fc'};
        
        function positionPanel(node) {
            const panel = document.getElementById('info-panel');
            const renderer = Graph.renderer();
            const camera = Graph.camera();
            const vec = new THREE.Vector3(node.x, node.y, node.z);
            vec.project(camera);
            const hw = renderer.domElement.clientWidth / 2;
            const hh = renderer.domElement.clientHeight / 2;
            let sx = (vec.x * hw) + hw;
            let sy = -(vec.y * hh) + hh;
            sx += 30;
            sy -= 40;
            const pw = 300, ph = panel.offsetHeight || 400, margin = 16;
            if (sx + pw > window.innerWidth - margin) sx = window.innerWidth - pw - margin;
            if (sx < margin) sx = margin;
            if (sy + ph > window.innerHeight - margin) sy = window.innerHeight - ph - margin;
            if (sy < margin) sy = margin;
            panel.style.left = sx + 'px';
            panel.style.top = sy + 'px';
        }
        
        function renderMasteryRing(mastery) {
            const circumference = 2 * Math.PI * 22;
            const offset = circumference * (1 - mastery);
            const fill = document.getElementById('ring-fill');
            fill.style.strokeDasharray = circumference;
            fill.style.strokeDashoffset = offset;
            const color = mastery >= 0.8 ? '#4ade80' : mastery >= 0.4 ? '#fbbf24' : mastery > 0 ? '#f87171' : 'rgba(255,255,255,0.2)';
            fill.style.stroke = color;
            document.getElementById('ring-pct').innerText = Math.round(mastery * 100) + '%';
        }
        
        function renderBloomBadge(bloomLevel) {
            const badge = document.getElementById('bloom-badge');
            const lvl = Math.max(1, Math.min(6, Math.ceil(bloomLevel || 0)));
            const label = BLOOM_LABELS[lvl] || 'Chưa đánh giá';
            const color = BLOOM_COLORS[lvl] || '#60a5fa';
            badge.style.background = color + '22';
            badge.style.color = color;
            badge.innerText = bloomLevel > 0 ? ('L' + lvl + ' ' + label) : '⏳ Chưa đánh giá';
        }
        
        function renderMiniBloom(nodeId) {
            const container = document.getElementById('mini-bloom-bars');
            container.innerHTML = '';
            for (let lvl = 1; lvl <= 3; lvl++) {
                const bloom = getBloomLevel(nodeId);
                const pct = bloom >= lvl ? 100 : (bloom >= lvl - 1 ? (bloom - (lvl-1)) * 100 : 0);
                const color = BLOOM_COLORS[lvl];
                container.innerHTML += `<div class="mini-bloom"><span class="lbl">L${lvl}</span><div class="bar"><div class="fill" style="width:${Math.round(pct)}%;background:${color}"></div></div><span class="val">${Math.round(pct)}%</span></div>`;
            }
        }
        
        function hasLearningResources(node) {
            const resources = node.resources || [];
            if (resources.length > 0) return true;
            const children = node.micro_children || [];
            return children.some(c => (c.resources || []).length > 0);
        }

        function toggleLesson(idx) {
            const el = document.getElementById('lg_' + idx);
            if (el) el.classList.toggle('open');
        }
        
        function renderLearnResources(node) {
            const container = document.getElementById('learn-resources');
            container.innerHTML = '';
            const children = node.micro_children || [];
            if (children.length === 0) {
                const resources = node.resources || [];
                resources.slice(0, 5).forEach(r => {
                    if (!r || !r.url) return;
                    const icon = r.icon || '📎';
                    const title = r.title || 'Tài nguyên';
                    const short = title.length > 35 ? title.substring(0, 32) + '...' : title;
                    const safeUrl = (r.url || '#').replace(/'/g, "\\'");
                    const isDoc = r.type === 'pdf' || (safeUrl.indexOf('.pdf') > -1) || (safeUrl.indexOf('drive.google.com') > -1 && safeUrl.indexOf('/view') > -1) || r.type === 'youtube' || (safeUrl.indexOf('.mp4') > -1) || (safeUrl.indexOf('.html') > -1 && safeUrl.indexOf('quiz') === -1);
                    if (isDoc) {
                        container.innerHTML += '<div class="res-card" title="' + title + '" onclick="startActionForResource(\'' + node.id + '\', \'video\', \'' + safeUrl + '\')" style="cursor:pointer; border-color:rgba(56,189,248,0.3);">' + icon + ' ' + short + '</div>';
                    } else {
                        container.innerHTML += '<div class="res-card" title="' + title + '" onclick="window.open(\'' + safeUrl + '\', \'_blank\')" style="cursor:pointer; border-color:rgba(56,189,248,0.3);">' + icon + ' ' + short + '</div>';
                    }
                });
                return;
            }
            const stepColors = ['#3b82f6','#8b5cf6','#06b6d4','#10b981','#f59e0b','#ef4444','#ec4899','#6366f1','#14b8a6','#f97316','#84cc16','#e879f9'];
            children.forEach((child, idx) => {
                const mastery = USER_STATE.mastery[child.id] || 0;
                const mPct = Math.round(mastery * 100);
                const color = stepColors[idx % stepColors.length];
                const mColor = mastery >= 0.8 ? 'var(--green)' : mastery >= 0.4 ? 'var(--yellow)' : 'rgba(255,255,255,0.3)';
                const mBg = mastery >= 0.8 ? 'rgba(74,222,128,0.15)' : mastery >= 0.4 ? 'rgba(251,191,36,0.15)' : 'rgba(255,255,255,0.05)';
                const groupId = 'lg_' + idx;
                const title = child.title || ('Bài ' + (idx + 1));
                const shortTitle = title.length > 28 ? title.substring(0, 26) + '…' : title;
                let html = '<div class="lesson-group">';
                html += '<div class="lesson-header" onclick="toggleLesson(' + idx + ')">';
                html += '<div class="lesson-step" style="background:' + color + '">' + (idx + 1) + '</div>';
                html += '<div class="lesson-title">' + shortTitle + '</div>';
                html += '<div class="lesson-mastery" style="color:' + mColor + ';background:' + mBg + '">' + mPct + '%</div>';
                html += '</div>';
                html += '<div class="lesson-resources" id="' + groupId + '">';
                const res = child.resources || [];
                if (res.length === 0) {
                    html += '<div class="lesson-res-item" style="opacity:0.4">Chưa có tài nguyên</div>';
                } else {
                    res.forEach(r => {
                        if (!r) return;
                        const rIcon = r.type === 'youtube' ? '🎬' : r.type === 'pdf' ? '📄' : r.type === 'document' ? '📝' : r.type === 'link' ? '🔗' : '📎';
                        const rTitle = (r.title || 'Tài nguyên');
                        const rShort = rTitle.length > 30 ? rTitle.substring(0, 28) + '…' : rTitle;
                        const safeUrl = (r.url || '#').replace(/'/g, "\\'");
                        const isDoc = r.type === 'pdf' || (safeUrl.indexOf('.pdf') > -1) || (safeUrl.indexOf('drive.google.com') > -1 && safeUrl.indexOf('/view') > -1) || r.type === 'youtube' || (safeUrl.indexOf('.mp4') > -1) || (safeUrl.indexOf('.html') > -1 && safeUrl.indexOf('quiz') === -1);
                        if (isDoc) {
                            html += '<div class="lesson-res-item" title="' + rTitle + '" onclick="startActionForResource(\'' + child.id + '\', \'video\', \'' + safeUrl + '\')">';
                        } else {
                            html += '<div class="lesson-res-item" title="' + rTitle + '" onclick="window.open(\'' + safeUrl + '\', \'_blank\')">';
                        }
                        html += '<span class="lesson-res-icon">' + rIcon + '</span> <span style="text-decoration: underline; text-decoration-color: rgba(255,255,255,0.2);">' + rShort + '</span>';
                        html += '</div>';
                    });
                }
                html += '</div></div>';
                container.innerHTML += html;
            });
            // Auto-expand first lesson - Disabled per user request
            // const firstGroup = document.getElementById('lg_0');
            // if (firstGroup) firstGroup.classList.add('open');
        }

        function init() {
            updateStats();
            renderChapterNav();
            Graph = ForceGraph3D()(document.getElementById('3d-graph'))
                .graphData(GRAPH_DATA)
                .backgroundColor('#060714')
                .showNavInfo(false)
                .dagMode('radialout')
                .dagLevelDistance(65)
                .d3AlphaDecay(0.02)
                .d3VelocityDecay(0.3)
                .warmupTicks(80)
                .cooldownTicks(120)
                .nodeVal('val')
                .nodeLabel(n => (isLocked(n) ? '🔒 ' : '') + (n.label || n.id))
                .nodeThreeObject(node => {
                    const group = new THREE.Group();
                    const color = new THREE.Color(getNodeColor(node));
                    if (node.type === 'macro') {
                        // ★ STAR/SUN style for Chapters
                        const coreGeo = new THREE.IcosahedronGeometry(node.val / 2.2, 2);
                        const coreMat = new THREE.MeshPhongMaterial({
                            color: color, emissive: color, emissiveIntensity: 0.8,
                            transparent: true, opacity: 0.95, shininess: 120
                        });
                        group.add(new THREE.Mesh(coreGeo, coreMat));
                        // Inner glow sphere
                        const glowGeo = new THREE.SphereGeometry(node.val / 1.8, 24, 16);
                        const glowMat = new THREE.MeshBasicMaterial({
                            color: color, transparent: true, opacity: 0.12, side: THREE.BackSide
                        });
                        group.add(new THREE.Mesh(glowGeo, glowMat));
                        // Orbital ring
                        const ringGeo = new THREE.TorusGeometry(node.val / 1.6, 0.35, 16, 64);
                        const ringMat = new THREE.MeshBasicMaterial({ color: color, transparent: true, opacity: 0.25 });
                        const ring = new THREE.Mesh(ringGeo, ringMat);
                        ring.rotation.x = Math.PI / 2.5;
                        group.add(ring);
                        // Second ring perpendicular
                        const ring2Geo = new THREE.TorusGeometry(node.val / 1.4, 0.2, 16, 64);
                        const ring2Mat = new THREE.MeshBasicMaterial({ color: 0xffffff, transparent: true, opacity: 0.08 });
                        const ring2 = new THREE.Mesh(ring2Geo, ring2Mat);
                        ring2.rotation.x = Math.PI / 1.5;
                        ring2.rotation.y = Math.PI / 4;
                        group.add(ring2);
                    } else {
                        // ● PLANET style for Meso lessons
                        const mastery = getMasteryLevel(node.id);
                        const bloom = getBloomLevel(node.id);
                        const radius = node.val / 2.8;
                        const coreGeo = new THREE.SphereGeometry(radius, 24, 18);
                        const coreMat = new THREE.MeshPhongMaterial({
                            color: color, emissive: color,
                            emissiveIntensity: mastery > 0.5 ? 0.6 : 0.25,
                            transparent: true, opacity: isLocked(node) ? 0.2 : 0.92,
                            shininess: 80
                        });
                        group.add(new THREE.Mesh(coreGeo, coreMat));
                        // Atmosphere glow
                        if (!isLocked(node)) {
                            const atmoGeo = new THREE.SphereGeometry(radius * 1.35, 24, 18);
                            const atmoMat = new THREE.MeshBasicMaterial({
                                color: color, transparent: true, opacity: 0.08, side: THREE.BackSide
                            });
                            group.add(new THREE.Mesh(atmoGeo, atmoMat));
                        }
                        // Next-best pulsing ring
                        if (node.next_best) {
                            const pulseGeo = new THREE.TorusGeometry(radius * 1.6, 0.5, 16, 48);
                            const pulseMat = new THREE.MeshBasicMaterial({ color: 0x38bdf8, transparent: true, opacity: 0.7 });
                            const pulseRing = new THREE.Mesh(pulseGeo, pulseMat);
                            pulseRing.rotation.x = Math.PI / 2;
                            group.add(pulseRing);
                        }
                        // Mastery ring indicator
                        if (mastery > 0.1 && !isLocked(node)) {
                            const mRingGeo = new THREE.TorusGeometry(radius * 1.2, 0.25, 8, 48, Math.PI * 2 * mastery);
                            const mColor = mastery >= 0.8 ? 0x4ade80 : mastery >= 0.4 ? 0xfbbf24 : 0xf87171;
                            const mRingMat = new THREE.MeshBasicMaterial({ color: mColor, transparent: true, opacity: 0.6 });
                            const mRing = new THREE.Mesh(mRingGeo, mRingMat);
                            mRing.rotation.x = Math.PI / 2;
                            group.add(mRing);
                        }
                    }
                    // Premium label - always visible above nodes
                    const label = new SpriteText(getShortLabel(node));
                    label.color = '#ffffff';
                    label.textHeight = node.type === 'macro' ? 3.5 : 2;
                    label.backgroundColor = node.type === 'macro' ? 'rgba(15,20,50,0.85)' : 'rgba(10,15,40,0.75)';
                    label.padding = node.type === 'macro' ? [3, 6] : [2, 4];
                    label.borderRadius = node.type === 'macro' ? 6 : 4;
                    label.borderWidth = node.type === 'macro' ? 0.5 : 0;
                    label.borderColor = 'rgba(56,189,248,0.3)';
                    label.fontFace = 'Inter, sans-serif';
                    label.fontWeight = node.type === 'macro' ? '700' : '500';
                    // Position label well above the node to prevent overlap
                    const yOff = node.type === 'macro' ? node.val / 1.2 + 8 : node.val / 2 + 6;
                    label.position.set(0, yOff, 0);
                    // Disable depth test so labels always render on top
                    label.material.depthTest = false;
                    label.material.depthWrite = false;
                    label.renderOrder = 999;
                    group.add(label);
                    return group;
                })
                .nodeThreeObjectExtend(false)
                .linkColor(link => {
                    if (link.relation === 'macro_path') return 'rgba(100, 160, 255, 0.35)';
                    if (link.relation === 'contains') return 'rgba(56, 189, 248, 0.18)';
                    return 'rgba(251, 191, 36, 0.35)';
                })
                .linkWidth(link => link.relation === 'macro_path' ? 2 : (link.relation === 'contains' ? 0.5 : 1))
                .linkDirectionalArrowLength(link => link.relation === 'contains' ? 0 : 4)
                .linkDirectionalArrowRelPos(0.9)
                .linkDirectionalArrowColor(link => link.relation === 'macro_path' ? 'rgba(100,160,255,0.5)' : 'rgba(251,191,36,0.5)')
                .linkDirectionalParticles(link => link.relation === 'prerequisite_for' ? 4 : (link.relation === 'macro_path' ? 3 : 1))
                .linkDirectionalParticleWidth(link => link.relation === 'macro_path' ? 2.5 : 1.5)
                .linkDirectionalParticleSpeed(0.004)
                .linkDirectionalParticleColor(link => {
                    if (link.relation === 'macro_path') return 'rgba(100,180,255,0.8)';
                    if (link.relation === 'contains') return 'rgba(56,189,248,0.5)';
                    return 'rgba(251,191,36,0.7)';
                })
                .linkCurvature(link => link.relation === 'prerequisite_for' ? 0.2 : 0.08)
                .linkOpacity(0.6)
                .onBackgroundClick(() => closePanel())
                .onNodeClick(n => {
                    if (isLocked(n)) return;
                    Graph.cameraPosition({ x: n.x*1.5, y: n.y*1.5, z: n.z*1.5 }, n, 1000);
                    window.currentNodeId = n.id;
                    const pType = document.getElementById('info-type');
                    pType.className = 'badge';
                    if (n.type === 'macro') {
                        pType.classList.add('type-macro');
                        pType.innerText = 'CHƯƠNG KIẾN THỨC';
                    } else {
                        pType.style.background = getNodeColor(n) + '33';
                        pType.style.color = getNodeColor(n);
                        pType.innerText = 'PHẦN BÀI HỌc';
                    }
                    document.getElementById('info-title').innerText = n.label || n.id;
                    const mastery = getMasteryLevel(n.id);
                    renderMasteryRing(mastery);
                    const bloom = getBloomLevel(n.id);
                    renderBloomBadge(bloom);
                    const statusText = mastery >= 0.8 ? 'Đã thành thạo' : mastery >= 0.4 ? 'Đang học' : 'Chưa bắt đầu';
                    document.getElementById('info-subtitle').innerText = statusText;
                    const learnSec = document.getElementById('learn-section');
                    if (n.type !== 'macro' && hasLearningResources(n)) {
                        learnSec.style.display = 'block';
                        renderLearnResources(n);
                    } else {
                        learnSec.style.display = 'none';
                    }
                    document.getElementById('assess-section').style.display = n.type === 'macro' ? 'none' : 'block';
                    if (n.type !== 'macro') renderMiniBloom(n.id);
                    const panel = document.getElementById('info-panel');
                    panel.classList.add('visible');
                    setTimeout(() => positionPanel(n), 50);
                });

            // ═══ CINEMATIC LIGHTING ═══
            const scene = Graph.scene();
            scene.add(new THREE.AmbientLight(0x1a1a3a, 1.5));
            const keyLight = new THREE.DirectionalLight(0x6090ff, 0.8);
            keyLight.position.set(150, 250, 100);
            scene.add(keyLight);
            const fillLight = new THREE.DirectionalLight(0xff6040, 0.3);
            fillLight.position.set(-100, -50, -100);
            scene.add(fillLight);
            const rimLight = new THREE.PointLight(0x38bdf8, 1.0, 800);
            rimLight.position.set(0, 120, 0);
            scene.add(rimLight);
            const accentLight = new THREE.PointLight(0x7c3aed, 0.5, 500);
            accentLight.position.set(-80, -40, 60);
            scene.add(accentLight);

            // ═══ STARFIELD BACKGROUND ═══
            const starGeo = new THREE.BufferGeometry();
            const starCount = 2500;
            const starPos = new Float32Array(starCount * 3);
            const starSizes = new Float32Array(starCount);
            for (let i = 0; i < starCount; i++) {
                starPos[i*3] = (Math.random() - 0.5) * 2000;
                starPos[i*3+1] = (Math.random() - 0.5) * 2000;
                starPos[i*3+2] = (Math.random() - 0.5) * 2000;
                starSizes[i] = Math.random() * 1.5 + 0.3;
            }
            starGeo.setAttribute('position', new THREE.BufferAttribute(starPos, 3));
            starGeo.setAttribute('size', new THREE.BufferAttribute(starSizes, 1));
            const starMat = new THREE.PointsMaterial({
                color: 0xccddff, size: 0.8, transparent: true, opacity: 0.7,
                sizeAttenuation: true, blending: THREE.AdditiveBlending
            });
            scene.add(new THREE.Points(starGeo, starMat));
            // Nebula cloud (second layer, warmer stars)
            const nebGeo = new THREE.BufferGeometry();
            const nebPos = new Float32Array(500 * 3);
            for (let i = 0; i < 500; i++) {
                nebPos[i*3] = (Math.random() - 0.5) * 1200;
                nebPos[i*3+1] = (Math.random() - 0.5) * 600;
                nebPos[i*3+2] = (Math.random() - 0.5) * 1200;
            }
            nebGeo.setAttribute('position', new THREE.BufferAttribute(nebPos, 3));
            const nebMat = new THREE.PointsMaterial({
                color: 0x6040ff, size: 2.0, transparent: true, opacity: 0.15,
                sizeAttenuation: true, blending: THREE.AdditiveBlending
            });
            scene.add(new THREE.Points(nebGeo, nebMat));

            // ═══ POST-PROCESSING BLOOM ═══
            try {
                const renderer = Graph.renderer();
                renderer.toneMapping = THREE.ReinhardToneMapping;
                renderer.toneMappingExposure = 1.2;
                const composer = new THREE.EffectComposer(renderer);
                const renderPass = new THREE.RenderPass(scene, Graph.camera());
                composer.addPass(renderPass);
                const bloomPass = new THREE.UnrealBloomPass(
                    new THREE.Vector2(window.innerWidth, window.innerHeight),
                    0.8, 0.4, 0.85
                );
                composer.addPass(bloomPass);
                // Override render loop
                const origTick = Graph._animationCycle || null;
                (function animate() {
                    requestAnimationFrame(animate);
                    composer.render();
                })();
            } catch(bErr) {
                console.log('Bloom postprocessing not available:', bErr);
            }

            // ═══ CINEMATIC INTRO ═══
            Graph.cameraPosition({ x: 0, y: 0, z: 500 }, { x: 0, y: 0, z: 0 }, 0);
            setTimeout(() => {
                Graph.cameraPosition({ x: 80, y: 40, z: 200 }, { x: 0, y: 0, z: 0 }, 2500);
            }, 800);

            document.getElementById('loading-screen').style.opacity = '0';
            setTimeout(() => document.getElementById('loading-screen').remove(), 1000);
            setTimeout(() => renderProgressBar(), 1500);

            window.addEventListener('resize', () => {
                const w = window.innerWidth || document.documentElement.clientWidth;
                const h = window.innerHeight || document.documentElement.clientHeight;
                if(Graph && w > 0 && h > 0) {
                    Graph.width(w).height(h);
                }
            });
            setTimeout(() => window.dispatchEvent(new Event('resize')), 500);
        }
        // Safety: always dismiss loading after 5s even if error
        setTimeout(() => {
            const ls = document.getElementById('loading-screen');
            if (ls) { ls.style.opacity = '0'; setTimeout(() => ls.remove(), 500); }
        }, 5000);
        window.addEventListener('DOMContentLoaded', function() {
            try { init(); } catch(e) {
                console.error('Galaxy init error:', e);
                const ls = document.getElementById('loading-screen');
                if (ls) { ls.style.opacity = '0'; setTimeout(() => ls.remove(), 500); }
            }
        });
        setInterval(() => {
            fetch(`/user_data/thangtt/states/student_state.json?t=${Date.now()}`)
                .then(r => r.json())
                .then(data => { 
                    if(data) { 
                        if(data.nodes_mastery) USER_STATE.mastery = data.nodes_mastery; 
                        if(data.inferred_blooms) USER_STATE.inferred_blooms = data.inferred_blooms;
                        updateStats(); 
                        if(Graph) Graph.nodeColor(getNodeColor);
                    } 
                })
                .catch(e => console.log(e));
        }, 5000);
    